package io.invenlio.fulfillment;
import io.invenlio.inventory.InventoryFulfillment;import io.invenlio.organization.*;import io.invenlio.sales.SalesFulfillmentAccess;import io.invenlio.warehouse.WarehouseAvailability;import java.math.*;import java.sql.Timestamp;import java.time.Instant;import java.util.*;import org.springframework.jdbc.core.JdbcTemplate;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;
@Service class FulfillmentService{private final AuthorizationService auth;private final AuditTrail audit;private final JdbcTemplate db;private final SalesFulfillmentAccess sales;private final InventoryFulfillment inventory;private final WarehouseAvailability warehouses;private final org.springframework.context.ApplicationEventPublisher events;FulfillmentService(AuthorizationService a,AuditTrail u,JdbcTemplate d,SalesFulfillmentAccess s,InventoryFulfillment i,WarehouseAvailability w,org.springframework.context.ApplicationEventPublisher e){auth=a;audit=u;db=d;sales=s;inventory=i;warehouses=w;events=e;}
 @Transactional PickList createPickList(UUID orderId,UUID packingLocationId){var a=auth.require(Permission.PICKING_MANAGE);var o=sales.requireAllocated(a.tenantId(),orderId);if(!Set.of("NOT_STARTED","PACKED").contains(o.fulfillmentStatus()))throw error("FULFILLMENT_ALREADY_STARTED");var loc=warehouses.findUsableLocation(a.tenantId(),o.warehouseId(),packingLocationId).orElseThrow(()->error("PACKING_LOCATION_NOT_FOUND"));if(!"PACKING".equals(loc.type()))throw error("PACKING_LOCATION_REQUIRED");UUID id=UUID.randomUUID();db.update("INSERT INTO pick_lists(id,tenant_id,sales_order_id,sales_order_number_snapshot,warehouse_id,packing_location_id,status,created_by,created_at)VALUES(?,?,?,?,?,?,'CREATED',?,now())",id,a.tenantId(),orderId,o.number(),o.warehouseId(),packingLocationId,a.userId());Map<UUID,SalesFulfillmentAccess.Allocation> byReservation=new HashMap<>();o.allocations().forEach(x->byReservation.put(x.reservationId(),x));var allocations=inventory.allocations(a.tenantId(),byReservation.keySet());if(allocations.isEmpty())throw error("PICK_TASKS_REQUIRED");for(var salesAllocation:o.allocations()){BigDecimal allocated=allocations.stream().filter(x->x.reservationId().equals(salesAllocation.reservationId())).map(InventoryFulfillment.Allocation::quantity).reduce(BigDecimal.ZERO,BigDecimal::add);if(allocated.compareTo(salesAllocation.quantity())!=0)throw error("PICK_ALLOCATION_RECONCILIATION_FAILED");}int seq=0;for(var x:allocations){var sa=byReservation.get(x.reservationId());db.update("INSERT INTO pick_tasks(id,tenant_id,pick_list_id,sales_order_id,sales_order_line_id,inventory_reservation_id,reservation_allocation_id,variant_id,warehouse_id,source_location_id,destination_packing_location_id,lot_id,serial_id,required_quantity,unit_code,status,sequence)VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,'PENDING',?)",UUID.randomUUID(),a.tenantId(),id,orderId,sa.lineId(),x.reservationId(),x.allocationId(),x.variantId(),x.warehouseId(),x.locationId(),packingLocationId,x.lotId(),x.serialId(),x.quantity(),x.unitCode(),++seq);}audit.record(a,"PICK_LIST_CREATED","pick-list",id.toString());return pick(a.tenantId(),id);}
 @Transactional PickList start(UUID id,long version){var a=auth.require(Permission.PICKING_MANAGE);if(db.update("UPDATE pick_lists SET status='IN_PROGRESS',started_at=now(),version=version+1 WHERE tenant_id=? AND id=? AND status='CREATED' AND version=?",a.tenantId(),id,version)!=1)throw error("CONCURRENT_MODIFICATION");PickList p=pick(a.tenantId(),id);sales.pickingStarted(a.tenantId(),p.salesOrderId);audit.record(a,"PICK_LIST_STARTED","pick-list",id.toString());return p;}
 @Transactional PickList completeTask(UUID listId,UUID taskId,long version,String key){var a=auth.require(Permission.PICKING_MANAGE);PickList p=pick(a.tenantId(),listId);if(!"IN_PROGRESS".equals(p.status))throw error("PICK_LIST_NOT_IN_PROGRESS");Task t=task(a.tenantId(),listId,taskId,true);if("COMPLETED".equals(t.status))throw error("PICK_TASK_ALREADY_COMPLETED");UUID movement=inventory.consumeToPacking(a.tenantId(),a.userId(),a.subject(),t.reservationId,t.allocationId,p.packingLocationId,key);if(db.update("UPDATE pick_tasks SET status='COMPLETED',picked_quantity=required_quantity,completed_at=now(),version=version+1 WHERE tenant_id=? AND pick_list_id=? AND id=? AND status='PENDING' AND version=?",a.tenantId(),listId,taskId,version)!=1)throw error("CONCURRENT_MODIFICATION");boolean complete=db.queryForObject("SELECT NOT EXISTS(SELECT 1 FROM pick_tasks WHERE tenant_id=? AND pick_list_id=? AND status<>'COMPLETED')",Boolean.class,a.tenantId(),listId);if(complete)db.update("UPDATE pick_lists SET status='COMPLETED',completed_at=now(),version=version+1 WHERE tenant_id=? AND id=?",a.tenantId(),listId);sales.picked(a.tenantId(),p.salesOrderId,t.lineId,t.requiredQuantity,complete);audit.record(a,"PICK_TASK_COMPLETED","pick-task",taskId.toString());events.publishEvent(new FulfillmentEvents.PickTaskCompleted(a.tenantId(),listId,taskId,movement));if(complete)events.publishEvent(new FulfillmentEvents.PickListCompleted(a.tenantId(),listId,p.salesOrderId));return pick(a.tenantId(),listId);}
 @Transactional(readOnly=true)PickList getPick(UUID id){var a=auth.require(Permission.PICKING_READ);return pick(a.tenantId(),id);}@Transactional(readOnly=true)List<PickList>listPicks(UUID salesOrder,UUID warehouse,String status,int page,int size,String sort){var a=auth.require(Permission.PICKING_READ);page(page,size);String order=switch(sort==null?"createdAt":sort){case "createdAt"->"created_at DESC";case "status"->"status";case "orderNumber"->"sales_order_number_snapshot";default->throw error("INVALID_SORT");};return db.query("SELECT id FROM pick_lists WHERE tenant_id=? AND(?::uuid IS NULL OR sales_order_id=?::uuid)AND(?::uuid IS NULL OR warehouse_id=?::uuid)AND(?::text IS NULL OR status=?::text)ORDER BY "+order+",id OFFSET ? LIMIT ?",(r,n)->pick(a.tenantId(),(UUID)r.getObject(1)),a.tenantId(),salesOrder,salesOrder,warehouse,warehouse,status,status,page*size,size);}
 @Transactional PackingSession createSession(UUID pickId){var a=auth.require(Permission.PACKING_MANAGE);PickList p=pick(a.tenantId(),pickId);if(!"COMPLETED".equals(p.status))throw error("PICK_LIST_NOT_COMPLETED");UUID id=UUID.randomUUID();db.update("INSERT INTO packing_sessions(id,tenant_id,sales_order_id,pick_list_id,packing_location_id,status,created_at)VALUES(?,?,?,?,?,'OPEN',now())",id,a.tenantId(),p.salesOrderId,pickId,p.packingLocationId);sales.packingStarted(a.tenantId(),p.salesOrderId);audit.record(a,"PACKING_SESSION_CREATED","packing-session",id.toString());return session(a.tenantId(),id);}
 @Transactional PackageView createPackage(UUID sessionId,PackageCommand c){var a=auth.require(Permission.PACKING_MANAGE);PackingSession s=session(a.tenantId(),sessionId);if(!"OPEN".equals(s.status))throw error("PACKING_SESSION_NOT_OPEN");db.queryForObject("SELECT id FROM packing_sessions WHERE tenant_id=? AND id=? FOR UPDATE",UUID.class,a.tenantId(),sessionId);int n=db.queryForObject("SELECT count(*)+1 FROM fulfillment_packages WHERE tenant_id=? AND packing_session_id=?",Integer.class,a.tenantId(),sessionId);UUID id=UUID.randomUUID();db.update("INSERT INTO fulfillment_packages(id,tenant_id,packing_session_id,package_number,status,weight_grams,length_mm,width_mm,height_mm,created_at)VALUES(?,?,?,?,'OPEN',?,?,?,?,now())",id,a.tenantId(),sessionId,"PKG-"+n,c.weight,c.length,c.width,c.height);audit.record(a,"PACKAGE_CREATED","fulfillment-package",id.toString());return pkg(a.tenantId(),id);}
 @Transactional PackageView addItem(UUID sessionId,UUID packageId,UUID taskId,BigDecimal q){var a=auth.require(Permission.PACKING_MANAGE);PackingSession s=session(a.tenantId(),sessionId);PackageView p=pkg(a.tenantId(),packageId);if(!p.sessionId.equals(sessionId)||!"OPEN".equals(s.status)||!"OPEN".equals(p.status))throw error("PACKAGE_NOT_OPEN");Task t=task(a.tenantId(),s.pickListId,taskId,true);if(!"COMPLETED".equals(t.status)||q==null||q.signum()<=0||q.scale()>6)throw error("INVALID_PACKAGE_QUANTITY");if(t.serialId!=null&&Boolean.TRUE.equals(db.queryForObject("SELECT EXISTS(SELECT 1 FROM package_items WHERE tenant_id=? AND serial_id=?)",Boolean.class,a.tenantId(),t.serialId)))throw error("SERIAL_ALREADY_PACKED");BigDecimal packed=db.queryForObject("SELECT COALESCE(sum(quantity),0) FROM package_items WHERE tenant_id=? AND pick_task_id=?",BigDecimal.class,a.tenantId(),taskId);if(packed.add(q).compareTo(t.requiredQuantity)>0)throw error("PACKAGE_ITEM_EXCEEDS_PICKED_QUANTITY");db.update("INSERT INTO package_items(id,tenant_id,package_id,pick_task_id,sales_order_line_id,variant_id,lot_id,serial_id,quantity,unit_code,created_at)VALUES(?,?,?,?,?,?,?,?,?,?,now())",UUID.randomUUID(),a.tenantId(),packageId,taskId,t.lineId,t.variantId,t.lotId,t.serialId,q,t.unitCode);audit.record(a,"PACKAGE_ITEM_ADDED","fulfillment-package",packageId.toString());return pkg(a.tenantId(),packageId);}
 @Transactional PackageView completePackage(UUID sessionId,UUID packageId,long version){var a=auth.require(Permission.PACKING_MANAGE);session(a.tenantId(),sessionId);if(db.update("UPDATE fulfillment_packages SET status='PACKED',version=version+1 WHERE tenant_id=? AND packing_session_id=? AND id=? AND status='OPEN' AND version=? AND EXISTS(SELECT 1 FROM package_items WHERE tenant_id=? AND package_id=?)",a.tenantId(),sessionId,packageId,version,a.tenantId(),packageId)!=1)throw error("PACKAGE_NOT_COMPLETABLE");audit.record(a,"PACKAGE_COMPLETED","fulfillment-package",packageId.toString());return pkg(a.tenantId(),packageId);}
 @Transactional PackingSession completeSession(UUID id,long version){var a=auth.require(Permission.PACKING_MANAGE);PackingSession s=session(a.tenantId(),id);boolean ready=db.queryForObject("SELECT NOT EXISTS(SELECT 1 FROM fulfillment_packages WHERE tenant_id=? AND packing_session_id=? AND status<>'PACKED') AND EXISTS(SELECT 1 FROM fulfillment_packages WHERE tenant_id=? AND packing_session_id=?) AND NOT EXISTS(SELECT 1 FROM pick_tasks t WHERE t.tenant_id=? AND t.pick_list_id=? AND t.picked_quantity<>(SELECT COALESCE(sum(i.quantity),0)FROM package_items i JOIN fulfillment_packages p ON p.tenant_id=i.tenant_id AND p.id=i.package_id WHERE i.tenant_id=t.tenant_id AND i.pick_task_id=t.id AND p.packing_session_id=?))",Boolean.class,a.tenantId(),id,a.tenantId(),id,a.tenantId(),s.pickListId,id);if(!ready)throw error("PACKING_SESSION_INCOMPLETE");if(db.update("UPDATE packing_sessions SET status='PACKED',completed_at=now(),version=version+1 WHERE tenant_id=? AND id=? AND status='OPEN' AND version=?",a.tenantId(),id,version)!=1)throw error("CONCURRENT_MODIFICATION");Map<UUID,BigDecimal> byLine=new HashMap<>();db.query("SELECT t.sales_order_line_id,sum(i.quantity) FROM package_items i JOIN fulfillment_packages p ON p.tenant_id=i.tenant_id AND p.id=i.package_id JOIN pick_tasks t ON t.tenant_id=i.tenant_id AND t.id=i.pick_task_id WHERE i.tenant_id=? AND p.packing_session_id=? GROUP BY t.sales_order_line_id",rs->{byLine.put((UUID)rs.getObject(1),rs.getBigDecimal(2));},a.tenantId(),id);sales.packed(a.tenantId(),s.salesOrderId,byLine);audit.record(a,"PACKING_COMPLETED","packing-session",id.toString());events.publishEvent(new FulfillmentEvents.PackingCompleted(a.tenantId(),id,s.salesOrderId));return session(a.tenantId(),id);}
 @Transactional(readOnly=true)PackingSession getSession(UUID id){var a=auth.require(Permission.PACKING_READ);return session(a.tenantId(),id);}
 private PickList pick(UUID t,UUID id){var xs=db.query("SELECT id,sales_order_id,sales_order_number_snapshot,warehouse_id,packing_location_id,status,created_at,started_at,completed_at,version FROM pick_lists WHERE tenant_id=? AND id=?",(r,n)->new PickList((UUID)r.getObject(1),(UUID)r.getObject(2),r.getString(3),(UUID)r.getObject(4),(UUID)r.getObject(5),r.getString(6),r.getTimestamp(7).toInstant(),instant(r.getTimestamp(8)),instant(r.getTimestamp(9)),r.getLong(10),tasks(t,id)),t,id);if(xs.isEmpty())throw error("PICK_LIST_NOT_FOUND");return xs.getFirst();}private List<Task>tasks(UUID t,UUID id){return db.query("SELECT id,sales_order_line_id,inventory_reservation_id,reservation_allocation_id,variant_id,source_location_id,lot_id,serial_id,required_quantity,picked_quantity,unit_code,status,sequence,version FROM pick_tasks WHERE tenant_id=? AND pick_list_id=? ORDER BY sequence,id",(r,n)->new Task((UUID)r.getObject(1),(UUID)r.getObject(2),(UUID)r.getObject(3),(UUID)r.getObject(4),(UUID)r.getObject(5),(UUID)r.getObject(6),(UUID)r.getObject(7),(UUID)r.getObject(8),r.getBigDecimal(9),r.getBigDecimal(10),r.getString(11),r.getString(12),r.getInt(13),r.getLong(14)),t,id);}private Task task(UUID t,UUID l,UUID id,boolean lock){var xs=db.query("SELECT id,sales_order_line_id,inventory_reservation_id,reservation_allocation_id,variant_id,source_location_id,lot_id,serial_id,required_quantity,picked_quantity,unit_code,status,sequence,version FROM pick_tasks WHERE tenant_id=? AND pick_list_id=? AND id=?"+(lock?" FOR UPDATE":""),(r,n)->new Task((UUID)r.getObject(1),(UUID)r.getObject(2),(UUID)r.getObject(3),(UUID)r.getObject(4),(UUID)r.getObject(5),(UUID)r.getObject(6),(UUID)r.getObject(7),(UUID)r.getObject(8),r.getBigDecimal(9),r.getBigDecimal(10),r.getString(11),r.getString(12),r.getInt(13),r.getLong(14)),t,l,id);if(xs.isEmpty())throw error("PICK_TASK_NOT_FOUND");return xs.getFirst();}
 private PackingSession session(UUID t,UUID id){var xs=db.query("SELECT id,sales_order_id,pick_list_id,packing_location_id,status,created_at,completed_at,version FROM packing_sessions WHERE tenant_id=? AND id=?",(r,n)->new PackingSession((UUID)r.getObject(1),(UUID)r.getObject(2),(UUID)r.getObject(3),(UUID)r.getObject(4),r.getString(5),r.getTimestamp(6).toInstant(),instant(r.getTimestamp(7)),r.getLong(8),packages(t,id)),t,id);if(xs.isEmpty())throw error("PACKING_SESSION_NOT_FOUND");return xs.getFirst();}private List<PackageView>packages(UUID t,UUID s){return db.query("SELECT id FROM fulfillment_packages WHERE tenant_id=? AND packing_session_id=? ORDER BY package_number,id",(r,n)->pkg(t,(UUID)r.getObject(1)),t,s);}private PackageView pkg(UUID t,UUID id){var xs=db.query("SELECT id,packing_session_id,package_number,status,weight_grams,length_mm,width_mm,height_mm,version FROM fulfillment_packages WHERE tenant_id=? AND id=?",(r,n)->new PackageView((UUID)r.getObject(1),(UUID)r.getObject(2),r.getString(3),r.getString(4),(Long)r.getObject(5),(Long)r.getObject(6),(Long)r.getObject(7),(Long)r.getObject(8),r.getLong(9),items(t,(UUID)r.getObject(1))),t,id);if(xs.isEmpty())throw error("FULFILLMENT_PACKAGE_NOT_FOUND");return xs.getFirst();}private List<ItemView>items(UUID t,UUID packageId){return db.query("SELECT id,pick_task_id,sales_order_line_id,variant_id,lot_id,serial_id,quantity,unit_code FROM package_items WHERE tenant_id=? AND package_id=? ORDER BY created_at,id",(r,n)->new ItemView((UUID)r.getObject(1),(UUID)r.getObject(2),(UUID)r.getObject(3),(UUID)r.getObject(4),(UUID)r.getObject(5),(UUID)r.getObject(6),r.getBigDecimal(7),r.getString(8)),t,packageId);}private static Instant instant(Timestamp x){return x==null?null:x.toInstant();}private static void page(int p,int s){if(p<0||s<1||s>100)throw error("INVALID_PAGINATION");}private static FulfillmentException error(String c){return new FulfillmentException(c,c.replace('_',' ').toLowerCase());}
 record PackageCommand(Long weight,Long length,Long width,Long height){}record PickList(UUID id,UUID salesOrderId,String salesOrderNumber,UUID warehouseId,UUID packingLocationId,String status,Instant createdAt,Instant startedAt,Instant completedAt,long version,List<Task>tasks){}record Task(UUID id,UUID lineId,UUID reservationId,UUID allocationId,UUID variantId,UUID sourceLocationId,UUID lotId,UUID serialId,BigDecimal requiredQuantity,BigDecimal pickedQuantity,String unitCode,String status,int sequence,long version){}record ItemView(UUID id,UUID pickTaskId,UUID salesOrderLineId,UUID variantId,UUID lotId,UUID serialId,BigDecimal quantity,String unitCode){}record PackingSession(UUID id,UUID salesOrderId,UUID pickListId,UUID packingLocationId,String status,Instant createdAt,Instant completedAt,long version,List<PackageView>packages){}record PackageView(UUID id,UUID sessionId,String packageNumber,String status,Long weightGrams,Long lengthMm,Long widthMm,Long heightMm,long version,List<ItemView>items){}
}
